mapper.select:
SELECT * FROM user_delegate
WHERE grantor_id = #{userId} OR grantee_id = #{userId}
ORDER BY id DESC

mapper.update:
UPDATE user_delegate
SET status = #{toStatus},
    responded_at = CURRENT_TIMESTAMP(3)
WHERE grantor_id = #{grantorId}
  AND grantee_id = #{granteeId}
  AND status = #{fromStatus}
